INSERT INTO public.questions (code, subject, topic, difficulty, question_text, options, correct_answer, explanation)
VALUES
  ('mat-01', 'Matematika', 'Aljabar', 'easy', 'Jika 3x - 7 = 2x + 5, berapakah nilai dari 2x + 1?', '["23","25","27","21"]'::jsonb, 1, '3x - 2x = 5 + 7 sehingga x = 12. Maka 2x + 1 = 2(12) + 1 = 25.'),
  ('mat-02', 'Matematika', 'Fungsi Kuadrat', 'medium', 'Persamaan kuadrat x^2 - 5x + 6 = 0 memiliki akar-akar x1 dan x2. Nilai x1^2 + x2^2 adalah...', '["11","13","19","25"]'::jsonb, 1, 'x1 + x2 = 5 dan x1·x2 = 6. Maka x1^2 + x2^2 = (x1 + x2)^2 - 2(x1·x2) = 25 - 12 = 13.'),
  ('mat-03', 'Matematika', 'Trigonometri', 'easy', 'Nilai dari sin(30°) + cos(60°) adalah...', '["0.5","1","√3","0"]'::jsonb, 1, 'sin(30°) = 1/2 dan cos(60°) = 1/2, sehingga jumlahnya 1/2 + 1/2 = 1.'),
  ('mat-04', 'Matematika', 'Trigonometri', 'medium', 'Diketahui sin α = 3/5 dan α berada di kuadran II. Nilai cos α adalah...', '["4/5","-4/5","3/4","-3/4"]'::jsonb, 1, 'Dengan triple Pythagoras 3-4-5, |cos α| = 4/5. Karena di kuadran II nilai cos negatif, maka cos α = -4/5.'),
  ('mat-05', 'Matematika', 'Logaritma', 'medium', 'Hasil dari ²log 16 + ³log 27 - ⁵log 25 adalah...', '["4","5","6","7"]'::jsonb, 1, '²log 16 = 4, ³log 27 = 3, dan ⁵log 25 = 2. Jadi 4 + 3 - 2 = 5.'),
  ('mat-06', 'Matematika', 'Barisan dan Deret', 'easy', 'Suku ke-10 dari barisan aritmetika 4, 7, 10, 13, ... adalah...', '["28","31","34","37"]'::jsonb, 1, 'a = 4, b = 3. Un = a + (n - 1)b = 4 + 9(3) = 4 + 27 = 31.'),
  ('mat-07', 'Matematika', 'Peluang', 'easy', 'Dua buah dadu dilempar bersamaan satu kali. Peluang munculnya jumlah mata dadu sama dengan 7 adalah...', '["1/12","1/6","5/36","7/36"]'::jsonb, 1, 'Pasangan berjumlah 7 ada 6 buah: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) dari 36 ruang sampel. 6/36 = 1/6.'),
  ('mat-08', 'Matematika', 'Peluang', 'medium', 'Dari 6 siswa akan dipilih 2 siswa untuk menjadi ketua dan sekretaris kelas. Banyak cara pemilihan tersebut adalah...', '["15","30","12","36"]'::jsonb, 1, 'Karena jabatan berbeda (memperhatikan urutan), gunakan permutasi P(6,2) = 6 × 5 = 30 cara.'),
  ('mat-09', 'Matematika', 'Statistika', 'easy', 'Median dari data: 7, 4, 9, 5, 8, 6, 10 adalah...', '["6","7","8","7.5"]'::jsonb, 1, 'Data diurutkan: 4, 5, 6, 7, 8, 9, 10. Nilai tengah (data ke-4) adalah 7.'),
  ('mat-10', 'Matematika', 'Statistika', 'medium', 'Rata-rata nilai 9 siswa adalah 70. Jika nilai seorang siswa ditambahkan, rata-ratanya menjadi 72. Nilai siswa tersebut adalah...', '["88","90","92","86"]'::jsonb, 1, 'Total awal = 9 × 70 = 630. Total baru = 10 × 72 = 720. Nilai tambahan = 720 - 630 = 90.'),
  ('mat-11', 'Matematika', 'Fungsi Komposisi', 'medium', 'Diketahui f(x) = 2x + 3 dan g(x) = x - 4. Nilai (f ∘ g)(5) adalah...', '["5","7","9","11"]'::jsonb, 0, 'g(5) = 5 - 4 = 1. Maka (f ∘ g)(5) = f(1) = 2(1) + 3 = 5.'),
  ('mat-12', 'Matematika', 'Matriks', 'medium', 'Determinan dari matriks A = [[5, 3], [2, 4]] adalah...', '["14","26","12","8"]'::jsonb, 0, 'det(A) = (5 × 4) - (3 × 2) = 20 - 6 = 14.'),
  ('mat-13', 'Matematika', 'Limit Fungsi', 'hard', 'Nilai dari lim (x→2) (x^2 - 4) / (x - 2) adalah...', '["0","2","4","8"]'::jsonb, 2, 'Faktorkan pembilang: (x - 2)(x + 2)/(x - 2) = x + 2. Substitusi x = 2 menghasilkan 2 + 2 = 4.'),
  ('mat-14', 'Matematika', 'Turunan', 'hard', 'Jika f(x) = 3x^3 - 4x^2 + 6x - 5, maka nilai f''(2) adalah...', '["22","26","28","30"]'::jsonb, 1, 'f''(x) = 9x^2 - 8x + 6. Maka f''(2) = 9(4) - 8(2) + 6 = 36 - 16 + 6 = 26.'),
  ('mat-15', 'Matematika', 'Integral', 'hard', 'Hasil dari integral tentu ∫₀² (3x^2 + 2x) dx adalah...', '["10","12","14","16"]'::jsonb, 1, 'Antiturunannya adalah x^3 + x^2. Evaluasi dari 0 ke 2: (2^3 + 2^2) - 0 = 8 + 4 = 12.'),
  ('bio-01', 'Biologi', 'Sel', 'easy', 'Organel sel yang berfungsi sebagai pusat respirasi seluler dan penghasil energi (ATP) adalah...', '["Ribosom","Mitokondria","Lisosom","Badan Golgi"]'::jsonb, 1, 'Mitokondria dikenal sebagai powerhouse of the cell karena menghasilkan ATP melalui respirasi aerob.'),
  ('bio-02', 'Biologi', 'Sel', 'easy', 'Struktur sel yang hanya dimiliki oleh sel tumbuhan dan tidak dimiliki oleh sel hewan adalah...', '["Membran plasma dan inti sel","Dinding sel dan kloroplas","Mitokondria dan ribosom","Retikulum endoplasma dan lisosom"]'::jsonb, 1, 'Sel tumbuhan memiliki dinding sel selulosa dan plastida/kloroplas untuk fotosintesis.'),
  ('bio-03', 'Biologi', 'Genetika', 'medium', 'Persilangan monohibrid dominan penuh antara tanaman berbunga merah (MM) dan putih (mm) menghasilkan F1. Jika sesama F1 disilangkan, rasio fenotipe F2 adalah...', '["1 : 2 : 1","3 : 1","9 : 3 : 3 : 1","1 : 1"]'::jsonb, 1, 'F1 bergenotipe Mm. Persilangan Mm × Mm menghasilkan genotipe MM : Mm : mm = 1:2:1, dengan fenotipe Merah : Putih = 3 : 1.'),
  ('bio-04', 'Biologi', 'Genetika', 'medium', 'Basa nitrogen yang hanya ditemukan pada molekul RNA dan tidak ada pada DNA adalah...', '["Adenin","Guanin","Sitosin","Urasil"]'::jsonb, 3, 'DNA memiliki basa A, T, G, C, sedangkan RNA memiliki basa A, U (Urasil), G, C.'),
  ('bio-05', 'Biologi', 'Ekosistem', 'easy', 'Dalam rantai makanan di padang rumput, belalang yang memakan rumput berperan sebagai...', '["Produsen","Konsumen primer (tingkat I)","Konsumen sekunder (tingkat II)","Dekomposer"]'::jsonb, 1, 'Herbivora yang memakan produsen (tumbuhan) secara langsung menempati posisi konsumen tingkat I.'),
  ('bio-06', 'Biologi', 'Ekosistem', 'medium', 'Bakteri Rhizobium yang hidup pada bintil akar tanaman kacang-kacangan membentuk simbiosis...', '["Parasitisme","Komensalisme","Mutualisme","Amensalisme"]'::jsonb, 2, 'Rhizobium membantu fiksasi nitrogen untuk tanaman, sementara tanaman menyediakan nutrisi dan tempat hidup.'),
  ('bio-07', 'Biologi', 'Sistem Organ', 'easy', 'Pertukaran gas oksigen (O2) dan karbon dioksida (CO2) di dalam paru-paru manusia terjadi pada bagian...', '["Trakea","Bronkus","Alveolus","Laring"]'::jsonb, 2, 'Alveolus memiliki dinding sangat tipis dan dikelilingi kapiler darah sehingga efektif untuk difusi gas.'),
  ('bio-08', 'Biologi', 'Sistem Organ', 'medium', 'Enzim amilase (ptialin) yang terdapat di dalam air liur berfungsi untuk memecah...', '["Protein menjadi pepton","Lemak menjadi asam lemak","Amilum menjadi maltosa","Peptida menjadi asam amino"]'::jsonb, 2, 'Amilase menghidrolisis pati/amilum menjadi disakarida (maltosa) di rongga mulut.'),
  ('bio-09', 'Biologi', 'Sistem Organ', 'medium', 'Bagian nefron ginjal yang berfungsi melakukan proses filtrasi darah adalah...', '["Tubulus kontortus proksimal","Glomerulus","Lengkung Henle","Tubulus kolektivus"]'::jsonb, 1, 'Filtrasi (penyaringan darah) terjadi di glomerulus yang dikelilingi kapsula Bowman dan menghasilkan urine primer.'),
  ('bio-10', 'Biologi', 'Evolusi', 'medium', 'Sayap burung dan kaki depan kuda memiliki struktur dasar tulang yang sama namun fungsinya berbeda. Fenomena ini disebut...', '["Analogi","Homologi","Konvergensi","Mutasi"]'::jsonb, 1, 'Organ homolog memiliki asal evolusi dan struktur dasar sama meski fungsinya berevolusi berbeda.'),
  ('bio-11', 'Biologi', 'Metabolisme', 'hard', 'Reaksi terang pada fotosintesis berlangsung di dalam kloroplas tepatnya pada bagian...', '["Stroma","Tilakoid (grana)","Membran luar","Sitoplasma"]'::jsonb, 1, 'Reaksi terang terjadi di membran tilakoid yang mengandung klorofil, sedangkan siklus Calvin terjadi di stroma.'),
  ('bio-12', 'Biologi', 'Pembelahan Sel', 'medium', 'Pembelahan sel yang menghasilkan 4 sel anak dengan jumlah kromosom setengah dari sel induk (haploid) disebut...', '["Amitosis","Mitosis","Meiosis","Kariokinesis"]'::jsonb, 2, 'Meiosis (pembelahan reduksi) menghasilkan 4 sel gamet haploid (n) dari sel induk diploid (2n).'),
  ('bio-13', 'Biologi', 'Sistem Peredaran Darah', 'easy', 'Komponen darah yang berperan utama dalam proses pembekuan darah saat terjadi luka adalah...', '["Eritrosit","Leukosit","Trombosit","Plasma albumin"]'::jsonb, 2, 'Trombosit (keping darah) melepaskan trombokinase yang memicu perubahan protrombin menjadi trombin untuk membekukan darah.'),
  ('bio-14', 'Biologi', 'Sistem Saraf', 'hard', 'Bagian otak yang berperan utama dalam mengatur keseimbangan tubuh dan koordinasi gerak otot adalah...', '["Cerebrum","Cerebellum","Medula oblongata","Hipotalamus"]'::jsonb, 1, 'Cerebellum (otak kecil) mengoordinasikan gerakan halus, postur, dan keseimbangan tubuh.'),
  ('bio-15', 'Biologi', 'Bioteknologi', 'hard', 'Teknik penyisipan gen penghasil insulin manusia ke dalam plasmid bakteri E. coli merupakan contoh...', '["Kultur jaringan","DNA rekombinan","Fermentasi konvensional","Hibridoma"]'::jsonb, 1, 'Teknologi DNA rekombinan menggabungkan gen target dengan vektor plasmid untuk memproduksi hormon insulin.'),
  ('fis-01', 'Fisika', 'Gerak Lurus', 'easy', 'Sebuah mobil bergerak lurus beraturan dengan kecepatan 72 km/jam. Jarak yang ditempuh mobil dalam waktu 10 detik adalah...', '["100 m","200 m","360 m","720 m"]'::jsonb, 1, '72 km/jam = 72000 m / 3600 s = 20 m/s. Jarak s = v × t = 20 × 10 = 200 m.'),
  ('fis-02', 'Fisika', 'Hukum Newton', 'easy', 'Benda bermassa 4 kg diberi gaya mendatar konstan sebesar 20 N pada lantai licin. Percepatan yang dialami benda adalah...', '["4 m/s²","5 m/s²","16 m/s²","80 m/s²"]'::jsonb, 1, 'Berdasarkan Hukum II Newton: a = F / m = 20 / 4 = 5 m/s².'),
  ('fis-03', 'Fisika', 'Energi dan Usaha', 'easy', 'Sebuah batu bermassa 2 kg berada pada ketinggian 5 m di atas tanah (g = 10 m/s²). Energi potensial gravitasi batu tersebut adalah...', '["50 J","100 J","150 J","200 J"]'::jsonb, 1, 'Ep = m · g · h = 2 × 10 × 5 = 100 Joule.'),
  ('fis-04', 'Fisika', 'Energi Kinetik', 'medium', 'Benda bermassa 3 kg bergerak dengan kecepatan 4 m/s. Energi kinetik benda tersebut adalah...', '["12 J","24 J","36 J","48 J"]'::jsonb, 1, 'Ek = ½ · m · v² = ½ × 3 × 4² = 1.5 × 16 = 24 Joule.'),
  ('fis-05', 'Fisika', 'Gelombang', 'easy', 'Sebuah gelombang memiliki frekuensi 50 Hz dan panjang gelombang 2 m. Cepat rambat gelombang tersebut adalah...', '["25 m/s","52 m/s","100 m/s","200 m/s"]'::jsonb, 2, 'v = λ · f = 2 m × 50 Hz = 100 m/s.'),
  ('fis-06', 'Fisika', 'Listrik Dinamis', 'easy', 'Sebuah resistor 6 Ω dihubungkan ke sumber tegangan 12 V. Besar kuat arus listrik yang mengalir adalah...', '["0.5 A","2 A","6 A","72 A"]'::jsonb, 1, 'Berdasarkan Hukum Ohm: I = V / R = 12 V / 6 Ω = 2 Ampere.'),
  ('fis-07', 'Fisika', 'Listrik Dinamis', 'medium', 'Dua resistor masing-masing 6 Ω dan 3 Ω disusun secara paralel. Hambatan penggantinya adalah...', '["2 Ω","4.5 Ω","9 Ω","18 Ω"]'::jsonb, 0, '1/Rp = 1/6 + 1/3 = 3/6 = 1/2, sehingga Rp = 2 Ω.'),
  ('fis-08', 'Fisika', 'Daya Listrik', 'medium', 'Lampu bertuliskan 60 W / 220 V menyala normal selama 10 detik. Energi listrik yang digunakan lampu tersebut adalah...', '["6 J","60 J","600 J","2200 J"]'::jsonb, 2, 'Energi W = P × t = 60 W × 10 s = 600 Joule.'),
  ('fis-09', 'Fisika', 'Momentum', 'medium', 'Benda bermassa 2 kg bergerak dengan kelajuan 6 m/s. Besar momentum benda tersebut adalah...', '["3 kg·m/s","8 kg·m/s","12 kg·m/s","36 kg·m/s"]'::jsonb, 2, 'Momentum p = m · v = 2 × 6 = 12 kg·m/s.'),
  ('fis-10', 'Fisika', 'GLBB', 'medium', 'Benda jatuh bebas dari ketinggian 20 m tanpa kecepatan awal (g = 10 m/s²). Waktu yang diperlukan untuk mencapai tanah adalah...', '["1 s","2 s","4 s","5 s"]'::jsonb, 1, 'h = ½ g t² → 20 = 5 t² → t² = 4 → t = 2 detik.'),
  ('fis-11', 'Fisika', 'Fluida Statis', 'medium', 'Tekanan hidrostatis pada kedalaman 3 m di dalam air (ρ = 1000 kg/m³, g = 10 m/s²) adalah...', '["300 Pa","3.000 Pa","30.000 Pa","300.000 Pa"]'::jsonb, 2, 'Ph = ρ · g · h = 1000 × 10 × 3 = 30.000 Pa.'),
  ('fis-12', 'Fisika', 'Suhu dan Kalor', 'easy', 'Suhu 27°C jika dinyatakan dalam skala Kelvin adalah...', '["246 K","273 K","300 K","327 K"]'::jsonb, 2, 'T(K) = t(°C) + 273 = 27 + 273 = 300 K.'),
  ('fis-13', 'Fisika', 'Optik', 'hard', 'Sebuah lensa cembung memiliki jarak fokus 20 cm. Kekuatan lensa tersebut adalah...', '["2 dioptri","5 dioptri","0.05 dioptri","10 dioptri"]'::jsonb, 1, 'P = 100 / f(cm) = 100 / 20 = +5 dioptri.'),
  ('fis-14', 'Fisika', 'Listrik Statis', 'hard', 'Dua muatan listrik sejenis terpisah pada jarak r dan tolak-menolak dengan gaya F. Jika jaraknya diubah menjadi 2r, gaya tolak-menolaknya menjadi...', '["4F","2F","1/2 F","1/4 F"]'::jsonb, 3, 'Sesuai Hukum Coulomb, F berbanding terbalik dengan r². Jika r menjadi 2r, gaya menjadi 1/(2²) F = 1/4 F.'),
  ('fis-15', 'Fisika', 'Induksi Elektromagnetik', 'hard', 'Alat yang berfungsi untuk menaikkan atau menurunkan tegangan listrik arus bolak-balik (AC) adalah...', '["Kapasitor","Transformator","Galvanometer","Komutator"]'::jsonb, 1, 'Transformator (trafo step-up dan step-down) bekerja berdasarkan induksi elektromagnetik untuk mengubah tegangan AC.'),
  ('kim-01', 'Kimia', 'Struktur Atom', 'easy', 'Unsur Natrium (Na) memiliki nomor atom 11 dan nomor massa 23. Jumlah neutron dalam inti atom Na adalah...', '["11","12","23","34"]'::jsonb, 1, 'Jumlah neutron = Nomor massa - Nomor atom = 23 - 11 = 12.'),
  ('kim-02', 'Kimia', 'Sistem Periodik', 'easy', 'Unsur dengan nomor atom 17 (Cl) dalam sistem periodik unsur terletak pada golongan...', '["IA (Alkali)","IIA (Alkali Tanah)","VIIA (Halogen)","VIIIA (Gas Mulia)"]'::jsonb, 2, 'Konfigurasi Cl (17) adalah 2, 8, 7. Memiliki 7 elektron valensi sehingga termasuk golongan VIIA (Halogen).'),
  ('kim-03', 'Kimia', 'Ikatan Kimia', 'easy', 'Ikatan yang terbentuk akibat serah terima elektron antara atom logam dan nonlogam, seperti pada NaCl, disebut...', '["Ikatan kovalen nonpolar","Ikatan ion","Ikatan logam","Ikatan hidrogen"]'::jsonb, 1, 'Na melepas 1 elektron membentuk Na+ dan Cl menangkap 1 elektron membentuk Cl-, lalu berikatan secara elektrostatis (ikatan ion).'),
  ('kim-04', 'Kimia', 'Ikatan Kimia', 'medium', 'Senyawa berikut yang berikatan secara kovalen adalah...', '["KCl","MgO","CH4","CaF2"]'::jsonb, 2, 'CH4 (metana) terbentuk antara unsur nonlogam C dan H melalui pemakaian pasangan elektron bersama (kovalen).'),
  ('kim-05', 'Kimia', 'Stoikiometri', 'medium', 'Massa molekul relatif (Mr) dari CO2 jika diketahui Ar C = 12 dan Ar O = 16 adalah...', '["28","32","44","48"]'::jsonb, 2, 'Mr CO2 = Ar C + 2 × Ar O = 12 + 2(16) = 12 + 32 = 44.'),
  ('kim-06', 'Kimia', 'Stoikiometri', 'medium', 'Jumlah mol dari 18 gram air (H2O, Mr = 18) adalah...', '["0.5 mol","1 mol","2 mol","18 mol"]'::jsonb, 1, 'Mol (n) = massa / Mr = 18 g / 18 g/mol = 1 mol.'),
  ('kim-07', 'Kimia', 'Asam dan Basa', 'easy', 'Larutan yang memiliki nilai pH kurang dari 7 dan mengubah kertas lakmus biru menjadi merah bersifat...', '["Asam","Basa","Netral","Amfoter"]'::jsonb, 0, 'Larutan asam memiliki pH < 7 dan memerahkan kertas lakmus biru.'),
  ('kim-08', 'Kimia', 'Asam dan Basa', 'medium', 'Nilai pH dari larutan asam kuat HCl 0,01 M adalah...', '["1","2","3","12"]'::jsonb, 1, '[H+] = 0,01 M = 10^-2 M. Maka pH = -log(10^-2) = 2.'),
  ('kim-09', 'Kimia', 'Asam dan Basa', 'hard', 'Nilai pH dari larutan basa kuat NaOH 0,001 M adalah...', '["3","7","11","13"]'::jsonb, 2, '[OH-] = 10^-3 M → pOH = 3. Maka pH = 14 - 3 = 11.'),
  ('kim-10', 'Kimia', 'Reaksi Kimia', 'medium', 'Pada reaksi setara pembakaran metana: CH4 + a O2 → b CO2 + c H2O, nilai koefisien a, b, dan c berturut-turut adalah...', '["1, 1, 2","2, 1, 2","2, 2, 1","1, 2, 2"]'::jsonb, 1, 'CH4 + 2 O2 → CO2 + 2 H2O (jumlah C=1, H=4, O=4 di kedua ruas).'),
  ('kim-11', 'Kimia', 'Laju Reaksi', 'medium', 'Zat yang dapat mempercepat laju reaksi kimia dengan menurunkan energi aktivasi tanpa ikut bereaksi secara permanen disebut...', '["Inhibitor","Katalis","Reduktor","Solven"]'::jsonb, 1, 'Katalis menurunkan energi aktivasi reaksi dan terbentuk kembali di akhir reaksi.'),
  ('kim-12', 'Kimia', 'Redoks', 'hard', 'Bilangan oksidasi unsur Belerang (S) dalam senyawa asam sulfat (H2SO4) adalah...', '["+2","+4","+6","-2"]'::jsonb, 2, '2(+1) + S + 4(-2) = 0 → +2 + S - 8 = 0 → S = +6.'),
  ('kim-13', 'Kimia', 'Termokimia', 'medium', 'Reaksi kimia yang melepaskan kalor dari sistem ke lingkungan sehingga nilai ΔH bertanda negatif disebut reaksi...', '["Endoterm","Eksoterm","Isoterm","Adiabatik"]'::jsonb, 1, 'Reaksi eksoterm melepaskan energi panas ke lingkungan sehingga entalpi sistem berkurang (ΔH < 0).'),
  ('kim-14', 'Kimia', 'Hidrokarbon', 'easy', 'Rumus umum dari deret homolog Alkana adalah...', '["CnH2n","CnH2n+2","CnH2n-2","CnHn"]'::jsonb, 1, 'Alkana merupakan hidrokarbon jenuh berikatan tunggal dengan rumus umum CnH2n+2.'),
  ('kim-15', 'Kimia', 'Larutan Elektrolit', 'easy', 'Di antara zat berikut yang larutannya dalam air bersifat non-elektrolit adalah...', '["NaCl","HCl","Glukosa (C6H12O6)","KOH"]'::jsonb, 2, 'Glukosa tidak terionisasi menjadi ion-ion bebas dalam air sehingga tidak menghantarkan listrik.'),
  ('sej-01', 'Sejarah', 'Pergerakan Nasional', 'easy', 'Organisasi pergerakan nasional modern pertama di Indonesia yang berdiri pada tanggal 20 Mei 1908 adalah...', '["Sarekat Islam","Budi Utomo","Indische Partij","Perhimpunan Indonesia"]'::jsonb, 1, 'Budi Utomo didirikan pada 20 Mei 1908 oleh dr. Sutomo dan mahasiswa STOVIA, yang diperingati sebagai Hari Kebangkitan Nasional.'),
  ('sej-02', 'Sejarah', 'Pergerakan Nasional', 'easy', 'Ikrar Sumpah Pemuda dibacakan dalam Kongres Pemuda II yang berlangsung pada tanggal...', '["20 Mei 1908","28 Oktober 1928","17 Agustus 1945","1 Juni 1945"]'::jsonb, 1, 'Sumpah Pemuda dicetuskan pada 28 Oktober 1928 di Batavia yang menegaskan satu nusa, satu bangsa, dan satu bahasa Indonesia.'),
  ('sej-03', 'Sejarah', 'Kemerdekaan Indonesia', 'easy', 'Peristiwa pengamanan Ir. Soekarno dan Drs. Mohammad Hatta ke luar Jakarta oleh golongan pemuda pada 16 Agustus 1945 dikenal sebagai...', '["Peristiwa Rengasdengklok","Bandung Lautan Api","Serangan Umum 1 Maret","Peristiwa Tugu"]'::jsonb, 0, 'Golongan pemuda membawa Soekarno-Hatta ke Rengasdengklok untuk menjauhkan mereka dari pengaruh Jepang dan mempercepat proklamasi.'),
  ('sej-04', 'Sejarah', 'Kemerdekaan Indonesia', 'medium', 'Tokoh yang mengetik naskah Proklamasi Kemerdekaan Indonesia setelah mengalami penyempurnaan redaksi adalah...', '["Ahmad Subardjo","Sayuti Melik","Sukarni","B.M. Diah"]'::jsonb, 1, 'Sayuti Melik mengetik naskah proklamasi dengan beberapa perubahan kecil atas persetujuan bersama di rumah Laksamana Maeda.'),
  ('sej-05', 'Sejarah', 'Sejarah Indonesia', 'medium', 'Kerajaan maritim bercorak Buddha terbesar di Nusantara yang berpusat di Sumatera pada abad ke-7 hingga ke-13 adalah...', '["Majapahit","Sriwijaya","Singasari","Kutai"]'::jsonb, 1, 'Kerajaan Sriwijaya menguasai jalur perdagangan Selat Malaka dan menjadi pusat pembelajaran agama Buddha.'),
  ('sej-06', 'Sejarah', 'Sejarah Indonesia', 'medium', 'Sumpah Palapa yang bertujuan menyatukan Nusantara diucapkan oleh Mahapatih Gajah Mada pada masa Kerajaan...', '["Tarumanegara","Mataram Kuno","Majapahit","Kediri"]'::jsonb, 2, 'Gajah Mada mengucapkan Sumpah Palapa ketika dilantik menjadi Mahapatih Amangkubhumi Majapahit.'),
  ('sej-07', 'Sejarah', 'Mempertahankan Kemerdekaan', 'medium', 'Perjanjian antara Indonesia dan Belanda pada tahun 1949 yang menghasilkan pengakuan kedaulatan Indonesia (RIS) adalah...', '["Perjanjian Linggarjati","Perjanjian Renville","Konferensi Meja Bundar (KMB)","Perjanjian Roem-Royen"]'::jsonb, 2, 'Konferensi Meja Bundar di Den Haag berakhir dengan penyerahan/pengakuan kedaulatan pada 27 Desember 1949.'),
  ('sej-08', 'Sejarah', 'Sejarah Dunia', 'medium', 'Revolusi Industri pertama kali muncul pada abad ke-18 di negara...', '["Prancis","Inggris","Jerman","Amerika Serikat"]'::jsonb, 1, 'Revolusi Industri bermula di Inggris berkat penemuan mesin uap James Watt, ketersediaan batu bara, dan modal perdagangan.'),
  ('sej-09', 'Sejarah', 'Sejarah Dunia', 'hard', 'Konferensi Asia-Afrika (KAA) tahun 1955 yang melahirkan Dasasila Bandung diselenggarakan di kota...', '["Jakarta","Bandung","Bogor","Yogyakarta"]'::jsonb, 1, 'KAA berlangsung pada 18–24 April 1955 di Gedung Merdeka, Bandung, dan menjadi tonggak Gerakan Non-Blok.'),
  ('sej-10', 'Sejarah', 'Sejarah Dunia', 'hard', 'Perang Dingin pasca Perang Dunia II merupakan persaingan ideologi dan geopolitik antara Blok Barat pimpinan AS dan Blok Timur pimpinan...', '["Jerman","Uni Soviet","Jepang","Inggris"]'::jsonb, 1, 'Perang Dingin mempertentangkan blok kapitalis-liberal (AS) dengan blok komunis-sosialis (Uni Soviet).'),
  ('geo-01', 'Geografi', 'Peta dan Kartografi', 'easy', 'Pada peta berskala 1 : 500.000, jarak kota A dan B adalah 4 cm. Jarak sebenarnya kedua kota tersebut adalah...', '["2 km","20 km","200 km","50 km"]'::jsonb, 1, 'Jarak sebenarnya = 4 cm × 500.000 = 2.000.000 cm = 20 km.'),
  ('geo-02', 'Geografi', 'Geografi Indonesia', 'easy', 'Garis khayal yang membagi persebaran fauna Indonesia bagian barat (Asiatis) dan bagian tengah (Peralihan) adalah...', '["Garis Khatulistiwa","Garis Wallace","Garis Weber","Garis Bujur 0°"]'::jsonb, 1, 'Garis Wallace membatasi wilayah fauna Asiatis dengan wilayah Peralihan, sedangkan Garis Weber membatasi Peralihan dan Australis.'),
  ('geo-03', 'Geografi', 'Geologi', 'medium', 'Indonesia rawan gempa bumi dan gunung api karena terletak di pertemuan tiga lempeng tektonik utama, yaitu...', '["Eurasia, Indo-Australia, dan Pasifik","Amerika, Afrika, dan Eurasia","Nazca, Pasifik, dan Antartika","Arab, India, dan Afrika"]'::jsonb, 0, 'Kepulauan Indonesia berada pada zona tumbukan lempeng Eurasia, Indo-Australia, dan Pasifik.'),
  ('geo-04', 'Geografi', 'Atmosfer dan Iklim', 'easy', 'Lapisan atmosfer tempat berlangsungnya peristiwa cuaca seperti hujan, angin, dan awan adalah...', '["Stratosfer","Troposfer","Mesosfer","Termosfer"]'::jsonb, 1, 'Troposfer adalah lapisan atmosfer paling bawah (0–12 km) tempat seluruh fenomena cuaca terjadi.'),
  ('geo-05', 'Geografi', 'Iklim', 'medium', 'Angin muson barat yang bertiup dari Benua Asia menuju Benua Australia pada bulan Oktober–April menyebabkan sebagian besar wilayah Indonesia mengalami...', '["Musim kemarau","Musim penghujan","Musim dingin","Badai salju"]'::jsonb, 1, 'Angin muson barat melewati perairan Samudra Hindia yang luas sehingga membawa banyak uap air dan memicu musim hujan.'),
  ('geo-06', 'Geografi', 'Kependudukan', 'medium', 'Perpindahan penduduk dari daerah pedesaan menuju ke kota besar disebut...', '["Transmigrasi","Imigrasi","Urbanisasi","Emigrasi"]'::jsonb, 2, 'Urbanisasi adalah perpindahan penduduk dari desa ke kota yang mendorong pertumbuhan kawasan perkotaan.'),
  ('geo-07', 'Geografi', 'Geografi Indonesia', 'easy', 'Pembagian waktu di Indonesia terdiri atas WIB, WITA, dan WIT. Selisih waktu antara WIB dan WIT adalah...', '["1 jam","2 jam","3 jam","4 jam"]'::jsonb, 1, 'WIB (UTC+7), WITA (UTC+8), dan WIT (UTC+9), sehingga selisih WIB dan WIT adalah 2 jam.'),
  ('geo-08', 'Geografi', 'Litosfer', 'medium', 'Batuan yang terbentuk dari pendinginan dan pembekuan magma disebut...', '["Batuan sedimen","Batuan beku","Batuan metamorf","Batuan kapur"]'::jsonb, 1, 'Batuan beku (igneous rock) berasal dari magma pijar yang mendingin baik di dalam kerak bumi maupun di permukaan.'),
  ('geo-09', 'Geografi', 'Hidrosfer', 'hard', 'Proses penguapan air dari permukaan tumbuhan melalui stomata daun dalam siklus hidrologi disebut...', '["Evaporasi","Transpirasi","Kondensasi","Infiltrasi"]'::jsonb, 1, 'Transpirasi adalah pelepasan uap air dari jaringan tumbuhan hidup ke atmosfer.'),
  ('geo-10', 'Geografi', 'SIG dan Penginderaan Jauh', 'hard', 'Dalam Sistem Informasi Geografis (SIG), data yang menggambarkan bentuk rupa bumi seperti titik, garis, dan poligon disebut data...', '["Atribut","Vektor","Raster","Spektral"]'::jsonb, 1, 'Data spasial vektor merepresentasikan fitur geografis menggunakan koordinat titik, garis, dan area (poligon).'),
  ('eng-01', 'Bahasa Inggris', 'Tenses & Grammar', 'easy', 'Choose the correct verb form: "By the time we arrived at the ruins, the rival explorers ___ already found the map."', '["have","had","has","were"]'::jsonb, 1, 'Past Perfect Tense ("had + V3") is used for an action completed before another past action ("arrived").'),
  ('eng-02', 'Bahasa Inggris', 'Conditional Sentences', 'medium', 'Complete the sentence: "If I ___ the secret coordinates earlier, I would have reached the temple first."', '["know","knew","had known","would know"]'::jsonb, 2, 'Third Conditional expresses a past unreal situation: If + S + had + V3, S + would have + V3.'),
  ('eng-03', 'Bahasa Inggris', 'Passive Voice', 'easy', 'Change into passive voice: "The ancient scribes carved these runes centuries ago."', '["These runes are carved by the ancient scribes centuries ago.","These runes were carved by the ancient scribes centuries ago.","These runes have been carved by the ancient scribes centuries ago.","These runes was carved by the ancient scribes centuries ago."]'::jsonb, 1, '"These runes" is plural and the time marker "centuries ago" requires Simple Past Passive ("were + V3").'),
  ('eng-04', 'Bahasa Inggris', 'Vocabulary', 'easy', 'What is the closest synonym for the word "Meticulous" in "She examined the ancient manuscript with meticulous care"?', '["Careless","Thorough","Hasty","Superficial"]'::jsonb, 1, '"Meticulous" means showing great attention to detail; very careful and thorough.'),
  ('eng-05', 'Bahasa Inggris', 'Sentence Structure', 'medium', 'Select the grammatically correct sentence:', '["Neither the compass nor the torches was working properly.","Neither the compass nor the torches were working properly.","Neither the compass or the torches were working properly.","Neither the compass nor the torches is working properly."]'::jsonb, 1, 'With "neither...nor", the verb agrees with the closer subject ("the torches", plural → "were").'),
  ('eng-06', 'Bahasa Inggris', 'Conjunctions', 'medium', 'Fill in the blank: "___ the heavy tropical storm, the expedition team continued marching across the bridge."', '["Although","Despite","Because","Even though"]'::jsonb, 1, '"Despite" is a preposition followed by a noun phrase ("the heavy tropical storm"), whereas "although/even though" require a clause.'),
  ('eng-07', 'Bahasa Inggris', 'Reading Comprehension', 'medium', 'Passage: "Although solar energy is abundant, storing electricity efficiently remains a hurdle for remote islands." What is the main challenge mentioned?', '["Lack of sunlight on islands","Difficulty in storing generated power","High cost of building bridges","Too much wind interference"]'::jsonb, 1, 'The passage explicitly states that "storing electricity efficiently remains a hurdle".'),
  ('eng-08', 'Bahasa Inggris', 'Relative Clauses', 'easy', 'Choose the right relative pronoun: "The historian ___ deciphered the tablet won the royal medal."', '["which","whom","who","whose"]'::jsonb, 2, '"Who" refers to a person acting as the subject of the relative clause ("deciphered").'),
  ('eng-09', 'Bahasa Inggris', 'Modal Verbs', 'hard', '"The temple floor is dry and dusty; nobody ___ entered this chamber for decades."', '["must have","can have","should have","would have"]'::jsonb, 1, 'In negative deductions about the past ("nobody..."), "can have" (or "could have") expresses logical impossibility.'),
  ('eng-10', 'Bahasa Inggris', 'Vocabulary in Context', 'hard', 'What does "ambiguous" mean in the sentence "The treasure map contained an ambiguous clue that confused everyone"?', '["Crystal clear","Open to multiple interpretations","Completely erased","Mathematically proven"]'::jsonb, 1, '"Ambiguous" describes something unclear or having more than one possible meaning.'),
  ('eko-01', 'Ekonomi', 'Permintaan dan Penawaran', 'easy', 'Sesuai hukum permintaan, apabila harga suatu barang naik (ceteris paribus), maka jumlah barang yang diminta akan...', '["Meningkat","Menurun","Tetap sama","Tak terhingga"]'::jsonb, 1, 'Hukum permintaan menyatakan hubungan berbanding terbalik antara harga dan jumlah barang yang diminta.'),
  ('eko-02', 'Ekonomi', 'Pasar', 'easy', 'Bentuk pasar di mana hanya terdapat satu penjual atau produsen tunggal tanpa barang substitusi dekat disebut pasar...', '["Persaingan sempurna","Oligopoli","Monopoli","Monopolistik"]'::jsonb, 2, 'Pasar monopoli dikuasai oleh satu penjual tunggal yang menentukan harga dan pasokan produk unik.'),
  ('eko-03', 'Ekonomi', 'Inflasi', 'easy', 'Kenaikan harga barang dan jasa secara umum dan terus-menerus dalam jangka waktu tertentu disebut...', '["Deflasi","Inflasi","Devaluasi","Resesi"]'::jsonb, 1, 'Inflasi adalah kecenderungan naiknya harga secara umum dan berkelanjutan yang menurunkan daya beli uang.'),
  ('eko-04', 'Ekonomi', 'Kebijakan Ekonomi', 'medium', 'Untuk menekan laju inflasi yang tinggi, bank sentral dapat menerapkan kebijakan moneter kontraktif dengan cara...', '["Menurunkan suku bunga acuan","Menaikkan suku bunga acuan","Membeli surat berharga di pasar terbuka","Menurunkan cadangan kas minimum bank"]'::jsonb, 1, 'Menaikkan suku bunga mendorong masyarakat menabung dan mengurangi jumlah uang beredar sehingga inflasi mereda.'),
  ('eko-05', 'Ekonomi', 'Kebijakan Fiskal', 'medium', 'Instrumen utama kebijakan fiskal yang dilakukan pemerintah melalui APBN adalah pengaturan...', '["Suku bunga dan nilai tukar","Pajak dan belanja pemerintah","Cadangan devisa dan kurs","Operasi pasar terbuka"]'::jsonb, 1, 'Kebijakan fiskal mengatur penerimaan negara (terutama pajak) dan pengeluaran pemerintah (belanja negara).'),
  ('eko-06', 'Ekonomi', 'Akuntansi Dasar', 'easy', 'Persamaan dasar akuntansi yang benar adalah...', '["Aset = Utang - Modal","Aset = Utang + Modal","Modal = Aset + Utang","Utang = Aset + Modal"]'::jsonb, 1, 'Sumber kekayaan perusahaan (Aset) berasal dari kewajiban kepada pihak luar (Utang) ditambah hak pemilik (Modal).'),
  ('eko-07', 'Ekonomi', 'Akuntansi Dasar', 'medium', 'Sebuah usaha memiliki total aset Rp50.000.000 dan total utang Rp18.000.000. Besar ekuitas (modal) usaha tersebut adalah...', '["Rp68.000.000","Rp32.000.000","Rp18.000.000","Rp28.000.000"]'::jsonb, 1, 'Modal = Aset - Utang = Rp50.000.000 - Rp18.000.000 = Rp32.000.000.'),
  ('eko-08', 'Ekonomi', 'Konsep Dasar Ekonomi', 'easy', 'Nilai dari pilihan terbaik yang dikorbankan ketika seseorang memilih suatu alternatif disebut...', '["Biaya tetap","Biaya peluang (opportunity cost)","Biaya marginal","Biaya rata-rata"]'::jsonb, 1, 'Biaya peluang adalah manfaat yang hilang karena tidak memilih alternatif terbaik berikutnya.'),
  ('eko-09', 'Ekonomi', 'Pendapatan Nasional', 'hard', 'Total nilai barang dan jasa akhir yang diproduksi di dalam wilayah suatu negara dalam satu tahun disebut...', '["Produk Nasional Bruto (PNB)","Produk Domestik Bruto (PDB)","Pendapatan Perseorangan","Pendapatan Disposabel"]'::jsonb, 1, 'PDB (GDP) menghitung seluruh nilai tambah produksi di dalam batas geografis suatu negara tanpa memandang kewarganegaraan produsen.'),
  ('eko-10', 'Ekonomi', 'Perdagangan Internasional', 'hard', 'Kebijakan pemerintah membatasi jumlah fisik maksimum barang tertentu yang boleh diimpor dalam periode tertentu disebut...', '["Tarif bea masuk","Kuota impor","Subsidi ekspor","Dumping"]'::jsonb, 1, 'Kuota impor adalah pembatasan kuantitas barang impor untuk melindungi produsen dalam negeri.')
